package deckplan_test

import (
	"encoding/json"
	"reflect"
	"testing"
	"time"

	"example.com/ferryops/deckplan"
)

const casesJSONEx = `[{"Ops": [{"Op": "remaining"}, {"Op": "place", "S": ["PL-855"], "N": [12, 0]}, {"Op": "place", "S": ["PL-698"], "N": [5, 1]}, {"Op": "place", "S": ["PL-208"], "N": [5, 0]}, {"Op": "log"}, {"Op": "place", "S": ["PL-487"], "N": [15, 0]}, {"Op": "remaining"}, {"Op": "log"}]}, {"Ops": [{"Op": "place", "S": ["PL-723"], "N": [4, 0]}, {"Op": "place", "S": ["PL-951"], "N": [5, 0]}, {"Op": "place", "S": ["PL-508"], "N": [12, 0]}, {"Op": "place", "S": ["PL-830"], "N": [12, 0]}, {"Op": "place", "S": ["PL-394"], "N": [12, 0]}, {"Op": "place", "S": ["PL-736"], "N": [12, 0]}, {"Op": "place", "S": ["PL-707"], "N": [12, 0]}, {"Op": "place", "S": ["PL-813"], "N": [4, 0]}, {"Op": "remaining"}, {"Op": "log"}]}, {"Ops": [{"Op": "place", "S": ["PL-214"], "N": [12, 0]}, {"Op": "place", "S": ["PL-915"], "N": [15, 0]}, {"Op": "remaining"}, {"Op": "remaining"}, {"Op": "place", "S": ["PL-296"], "N": [8, 0]}, {"Op": "place", "S": ["PL-683"], "N": [5, 1]}, {"Op": "log"}, {"Op": "log"}, {"Op": "place", "S": ["PL-191"], "N": [5, 0]}, {"Op": "place", "S": ["PL-984"], "N": [0, 0]}, {"Op": "remaining"}, {"Op": "log"}]}]`

var clockNowEx time.Time

type opEx struct {
	Op string
	S  []string
	N  []int
}

type scenarioEx struct {
	Ops []opEx
}

func resEx(v any, err error) any {
	if err != nil {
		return map[string]any{"err": err.Error()}
	}
	return v
}

func normEx(v any) any {
	switch x := v.(type) {
	case []any:
		if len(x) == 0 {
			return nil
		}
		for i := range x {
			x[i] = normEx(x[i])
		}
		return x
	case map[string]any:
		for k := range x {
			x[k] = normEx(x[k])
		}
		return x
	}
	return v
}

func outcomesEx() []any {
	var scs []scenarioEx
	if err := json.Unmarshal([]byte(casesJSONEx), &scs); err != nil {
		panic(err)
	}
	var all []any
	for _, sc := range scs {
		b, _ := json.Marshal(runCaseEx(sc))
		var v any
		_ = json.Unmarshal(b, &v)
		all = append(all, normEx(v))
	}
	return all
}

func runCaseEx(sc scenarioEx) []any {
	clockNowEx = time.Unix(1_700_000_000, 0)
	d := deckplan.NewPlanner(deckplan.Config{Lanes: 4, LaneLength: 12})
	var out []any
	for _, o := range sc.Ops {
		switch o.Op {
		case "advance":
			clockNowEx = clockNowEx.Add(time.Duration(o.N[0]) * time.Second)
		case "place":
			lane, err := d.Place(deckplan.Vehicle{Plate: o.S[0], Metres: o.N[0], Dangerous: o.N[1] == 1})
			out = append(out, resEx(lane, err))
		case "remaining":
			out = append(out, d.Remaining())
		case "log":
			out = append(out, d.Log())
		}
	}
	return out
}
const wantJSONEx = `[[[12, 12, 12, 12], "L1", "L2", "L3", ["PL-855 -> L1", "PL-698 -> L2", "PL-208 -> L3"], {"err": "PL-487: length 15 m does not fit a lane of 12 m"}, [0, 7, 7, 12], ["PL-855 -> L1", "PL-698 -> L2", "PL-208 -> L3"]], ["L1", "L1", "L2", "L3", "L4", {"err": "no space for PL-736"}, {"err": "no space for PL-707"}, {"err": "no space for PL-813"}, [3, 0, 0, 0], ["PL-723 -> L1", "PL-951 -> L1", "PL-508 -> L2", "PL-830 -> L3", "PL-394 -> L4"]], ["L1", {"err": "PL-915: length 15 m does not fit a lane of 12 m"}, [0, 12, 12, 12], [0, 12, 12, 12], "L2", "L3", ["PL-214 -> L1", "PL-296 -> L2", "PL-683 -> L3"], ["PL-214 -> L1", "PL-296 -> L2", "PL-683 -> L3"], "L4", {"err": "PL-984: length 0 m does not fit a lane of 12 m"}, [0, 4, 7, 7], ["PL-214 -> L1", "PL-296 -> L2", "PL-683 -> L3", "PL-191 -> L4"]]]`

func TestExampleScenarios(t *testing.T) {
	var want []any
	if err := json.Unmarshal([]byte(wantJSONEx), &want); err != nil {
		t.Fatal(err)
	}
	got := outcomesEx()
	if len(got) != len(want) {
		t.Fatalf("got %d scenarios, want %d", len(got), len(want))
	}
	for i := range want {
		w := normEx(want[i])
		if !reflect.DeepEqual(got[i], w) {
			t.Errorf("scenarioEx %d:\n got  %v\n want %v", i, got[i], w)
		}
	}
}

