package deckplan_test

import (
	"encoding/json"
	"reflect"
	"testing"
	"time"

	"example.com/ferryops/deckplan"
)

const casesJSONEx = `[{"Ops": [{"Op": "place", "S": ["PL-875"], "N": [5, 1]}, {"Op": "place", "S": ["PL-714"], "N": [0, 0]}, {"Op": "remaining"}, {"Op": "place", "S": ["PL-579"], "N": [20, 0]}, {"Op": "remaining"}, {"Op": "log"}]}, {"Ops": [{"Op": "log"}, {"Op": "place", "S": ["PL-621"], "N": [5, 1]}, {"Op": "place", "S": ["PL-783"], "N": [5, 0]}, {"Op": "place", "S": ["PL-614"], "N": [20, 0]}, {"Op": "place", "S": ["PL-101"], "N": [4, 0]}, {"Op": "place", "S": ["PL-407"], "N": [5, 0]}, {"Op": "place", "S": ["PL-559"], "N": [5, 0]}, {"Op": "place", "S": ["PL-839"], "N": [8, 0]}, {"Op": "remaining"}, {"Op": "log"}]}, {"Ops": [{"Op": "remaining"}, {"Op": "place", "S": ["PL-998"], "N": [5, 0]}, {"Op": "remaining"}, {"Op": "place", "S": ["PL-178"], "N": [5, 0]}, {"Op": "remaining"}, {"Op": "remaining"}, {"Op": "log"}]}]`

var clockNowEx time.Time

type opEx struct {
	Op string
	S  []string
	N  []int
}

type scenarioEx struct {
	Ops []opEx
}

func resEx(v any, err error) any {
	if err != nil {
		return map[string]any{"err": err.Error()}
	}
	return v
}

func normEx(v any) any {
	switch x := v.(type) {
	case []any:
		if len(x) == 0 {
			return nil
		}
		for i := range x {
			x[i] = normEx(x[i])
		}
		return x
	case map[string]any:
		for k := range x {
			x[k] = normEx(x[k])
		}
		return x
	}
	return v
}

func outcomesEx() []any {
	var scs []scenarioEx
	if err := json.Unmarshal([]byte(casesJSONEx), &scs); err != nil {
		panic(err)
	}
	var all []any
	for _, sc := range scs {
		b, _ := json.Marshal(runCaseEx(sc))
		var v any
		_ = json.Unmarshal(b, &v)
		all = append(all, normEx(v))
	}
	return all
}

func runCaseEx(sc scenarioEx) []any {
	clockNowEx = time.Unix(1_700_000_000, 0)
	d := deckplan.NewPlanner(deckplan.Config{Lanes: 4, LaneLength: 20})
	var out []any
	for _, o := range sc.Ops {
		switch o.Op {
		case "advance":
			clockNowEx = clockNowEx.Add(time.Duration(o.N[0]) * time.Second)
		case "place":
			lane, err := d.Place(deckplan.Vehicle{Plate: o.S[0], Metres: o.N[0], Dangerous: o.N[1] == 1})
			out = append(out, resEx(lane, err))
		case "remaining":
			out = append(out, d.Remaining())
		case "log":
			out = append(out, d.Log())
		}
	}
	return out
}
const wantJSONEx = `[["L1", {"err": "PL-714: length 0 m does not fit a lane of 20 m"}, [15, 20, 20, 20], "L2", [15, 0, 20, 20], ["PL-875 -> L1", "PL-579 -> L2"]], [null, "L1", "L2", "L3", "L2", "L2", "L2", "L4", [15, 1, 0, 12], ["PL-621 -> L1", "PL-783 -> L2", "PL-614 -> L3", "PL-101 -> L2", "PL-407 -> L2", "PL-559 -> L2", "PL-839 -> L4"]], [[20, 20, 20, 20], "L1", [15, 20, 20, 20], "L1", [10, 20, 20, 20], [10, 20, 20, 20], ["PL-998 -> L1", "PL-178 -> L1"]]]`

func TestExampleScenarios(t *testing.T) {
	var want []any
	if err := json.Unmarshal([]byte(wantJSONEx), &want); err != nil {
		t.Fatal(err)
	}
	got := outcomesEx()
	if len(got) != len(want) {
		t.Fatalf("got %d scenarios, want %d", len(got), len(want))
	}
	for i := range want {
		w := normEx(want[i])
		if !reflect.DeepEqual(got[i], w) {
			t.Errorf("scenarioEx %d:\n got  %v\n want %v", i, got[i], w)
		}
	}
}

