            # char literal ('a', '\n', '\u{1F600}') versus lifetime ('a) in rust
            m = re.match(r"'(\\.[^']*|[^\\'])'", src[i:])
            if m:
                out.append("'" + " " * (len(m.group(0)) - 2) + "'")
                i += len(m.group(0))
                prev_sig = "'"
