package deckplan_test

import (
	"encoding/json"
	"reflect"
	"testing"
	"time"

	"example.com/ferryops/deckplan"
)

const casesJSONEx = `[{"Ops": [{"Op": "place", "S": ["PL-698"], "N": [19, 0]}, {"Op": "log"}, {"Op": "place", "S": ["PL-888"], "N": [19, 0]}, {"Op": "place", "S": ["PL-151"], "N": [0, 1]}, {"Op": "log"}, {"Op": "remaining"}, {"Op": "log"}]}, {"Ops": [{"Op": "place", "S": ["PL-948"], "N": [12, 0]}, {"Op": "place", "S": ["PL-226"], "N": [4, 1]}, {"Op": "place", "S": ["PL-885"], "N": [19, 0]}, {"Op": "place", "S": ["PL-119"], "N": [19, 0]}, {"Op": "log"}, {"Op": "place", "S": ["PL-151"], "N": [0, 0]}, {"Op": "place", "S": ["PL-660"], "N": [4, 0]}, {"Op": "place", "S": ["PL-829"], "N": [16, 0]}, {"Op": "remaining"}, {"Op": "place", "S": ["PL-737"], "N": [19, 0]}, {"Op": "remaining"}, {"Op": "log"}]}, {"Ops": [{"Op": "place", "S": ["PL-912"], "N": [12, 0]}, {"Op": "log"}, {"Op": "place", "S": ["PL-794"], "N": [12, 0]}, {"Op": "place", "S": ["PL-763"], "N": [8, 0]}, {"Op": "place", "S": ["PL-179"], "N": [2, 0]}, {"Op": "remaining"}, {"Op": "log"}]}]`

var clockNowEx time.Time

type opEx struct {
	Op string
	S  []string
	N  []int
}

type scenarioEx struct {
	Ops []opEx
}

func resEx(v any, err error) any {
	if err != nil {
		return map[string]any{"err": err.Error()}
	}
	return v
}

func normEx(v any) any {
	switch x := v.(type) {
	case []any:
		if len(x) == 0 {
			return nil
		}
		for i := range x {
			x[i] = normEx(x[i])
		}
		return x
	case map[string]any:
		for k := range x {
			x[k] = normEx(x[k])
		}
		return x
	}
	return v
}

func outcomesEx() []any {
	var scs []scenarioEx
	if err := json.Unmarshal([]byte(casesJSONEx), &scs); err != nil {
		panic(err)
	}
	var all []any
	for _, sc := range scs {
		b, _ := json.Marshal(runCaseEx(sc))
		var v any
		_ = json.Unmarshal(b, &v)
		all = append(all, normEx(v))
	}
	return all
}

func runCaseEx(sc scenarioEx) []any {
	clockNowEx = time.Unix(1_700_000_000, 0)
	d := deckplan.NewPlanner(deckplan.Config{Lanes: 4, LaneLength: 16})
	var out []any
	for _, o := range sc.Ops {
		switch o.Op {
		case "advance":
			clockNowEx = clockNowEx.Add(time.Duration(o.N[0]) * time.Second)
		case "place":
			lane, err := d.Place(deckplan.Vehicle{Plate: o.S[0], Metres: o.N[0], Dangerous: o.N[1] == 1})
			out = append(out, resEx(lane, err))
		case "remaining":
			out = append(out, d.Remaining())
		case "log":
			out = append(out, d.Log())
		}
	}
	return out
}
const wantJSONEx = `[[{"err": "PL-698: length 19 m does not fit a lane of 16 m"}, null, {"err": "PL-888: length 19 m does not fit a lane of 16 m"}, {"err": "PL-151: length 0 m does not fit a lane of 16 m"}, null, [16, 16, 16, 16], null], ["L1", "L2", {"err": "PL-885: length 19 m does not fit a lane of 16 m"}, {"err": "PL-119: length 19 m does not fit a lane of 16 m"}, ["PL-948 -> L1", "PL-226 -> L2"], {"err": "PL-151: length 0 m does not fit a lane of 16 m"}, "L1", "L3", [0, 12, 0, 16], {"err": "PL-737: length 19 m does not fit a lane of 16 m"}, [0, 12, 0, 16], ["PL-948 -> L1", "PL-226 -> L2", "PL-660 -> L1", "PL-829 -> L3"]], ["L1", ["PL-912 -> L1"], "L2", "L3", "L1", [2, 4, 8, 16], ["PL-912 -> L1", "PL-794 -> L2", "PL-763 -> L3", "PL-179 -> L1"]]]`

func TestExampleScenarios(t *testing.T) {
	var want []any
	if err := json.Unmarshal([]byte(wantJSONEx), &want); err != nil {
		t.Fatal(err)
	}
	got := outcomesEx()
	if len(got) != len(want) {
		t.Fatalf("got %d scenarios, want %d", len(got), len(want))
	}
	for i := range want {
		w := normEx(want[i])
		if !reflect.DeepEqual(got[i], w) {
			t.Errorf("scenarioEx %d:\n got  %v\n want %v", i, got[i], w)
		}
	}
}

