func envInt(name string, def int) int {
	if v, err := strconv.Atoi(os.Getenv(name)); err == nil {
		return v
	}
	return def
}

var (
	lanes      = envInt("FERRY_LANES", 4)
	laneLength = envInt("FERRY_LANE_METRES", 16)
	placed     = map[string][]Vehicle{}
	log        []string
)

// Vehicle is something that wants to board.
type Vehicle struct {
	Plate     string
	Metres    int
	Dangerous bool
