func norm(v any) any {
	switch x := v.(type) {
	case []any:
		if len(x) == 0 {
			return nil
		}
		for i := range x {
			x[i] = norm(x[i])
		}
		return x
	case map[string]any:
		for k := range x {
			x[k] = norm(x[k])
		}
		return x
	}
	return v
}

func outcomes() []any {
	var scs []scenario
	if err := json.Unmarshal([]byte(casesJSON), &scs); err != nil {
