	for _, sc := range scs {
		b, _ := json.Marshal(runCase(sc))
		var v any
		_ = json.Unmarshal(b, &v)
		all = append(all, norm(v))
	}
	return all
}

func runCase(sc scenario) []any {
	clockNow = time.Unix(1_700_000_000, 0)
	logBuf.Reset()
	d := badges.NewScanner(badges.Options{Clock: func() time.Time { return clockNow }, Log: &logBuf})
	var out []any
	for _, o := range sc.Ops {
		switch o.Op {
		case "advance":
			clockNow = clockNow.Add(time.Duration(o.N[0]) * time.Second)
		case "scan":
			out = append(out, d.Scan(o.S[0], o.S[1]))
		case "seen":
			out = append(out, d.Seen(o.S[0], o.S[1]))
		}
	}
	out = append(out, logBuf.String())
	return out
}
