		case "seen":
			out = append(out, d.Seen(o.S[0], o.S[1]))
		}
	}
	out = append(out, logBufEx.String())
	return out
}
const wantJSONEx = `[[true, false, false, false, false, false, false, "opened B-22@store\ndenied B-22@roof\ndenied B-99@lab\ndenied B-99@store\n"], [false, true, false, true, false, "denied B-22@lab\nopened B-58@server\nopened B-40@roof\n"], [true, true, true, false, false, true, false, false, "opened B-58@lab\nopened B-40@store\nopened B-40@roof\ndenied B-22@lab\ndenied B-99@store\nopened B-22@store\nignored repeat B-40@roof\ndenied B-58@roof\n"]]`

func TestExampleScenarios(t *testing.T) {
	var want []any
	if err := json.Unmarshal([]byte(wantJSONEx), &want); err != nil {
		t.Fatal(err)
	}
	got := outcomesEx()
	if len(got) != len(want) {
		t.Fatalf("got %d scenarios, want %d", len(got), len(want))
	}
	for i := range want {
		w := normEx(want[i])
		if !reflect.DeepEqual(got[i], w) {
			t.Errorf("scenarioEx %d:\n got  %v\n want %v", i, got[i], w)
		}
	}
}

