package badges_test

import (
	"bytes"
	"encoding/json"
	"reflect"
	"testing"
	"time"

	"example.com/doorcontrol/badges"
)

const casesJSONEx = `[{"Ops": [{"Op": "scan", "S": ["B-17", "lab"]}, {"Op": "seen", "S": ["B-17", "store"]}, {"Op": "scan", "S": ["B-40", "server"]}, {"Op": "seen", "S": ["B-99", "roof"]}, {"Op": "advance", "N": [29]}, {"Op": "seen", "S": ["B-40", "lab"]}, {"Op": "seen", "S": ["B-17", "store"]}, {"Op": "advance", "N": [9]}, {"Op": "scan", "S": ["B-40", "server"]}, {"Op": "scan", "S": ["B-99", "roof"]}, {"Op": "advance", "N": [5]}]}, {"Ops": [{"Op": "advance", "N": [120]}, {"Op": "advance", "N": [59]}, {"Op": "scan", "S": ["B-40", "server"]}, {"Op": "advance", "N": [4]}, {"Op": "advance", "N": [29]}, {"Op": "scan", "S": ["B-40", "roof"]}, {"Op": "advance", "N": [4]}, {"Op": "scan", "S": ["B-17", "roof"]}]}, {"Ops": [{"Op": "scan", "S": ["B-99", "store"]}, {"Op": "seen", "S": ["B-40", "lab"]}, {"Op": "scan", "S": ["B-22", "roof"]}, {"Op": "scan", "S": ["B-17", "store"]}, {"Op": "scan", "S": ["B-17", "lab"]}]}]`

var clockNowEx time.Time

var logBufEx bytes.Buffer

type opEx struct {
	Op string
	S  []string
	N  []int
}

type scenarioEx struct {
	Ops []opEx
}

func resEx(v any, err error) any {
	if err != nil {
		return map[string]any{"err": err.Error()}
	}
	return v
}

func normEx(v any) any {
	switch x := v.(type) {
	case []any:
		if len(x) == 0 {
			return nil
		}
		for i := range x {
			x[i] = normEx(x[i])
		}
		return x
	case map[string]any:
		for k := range x {
			x[k] = normEx(x[k])
		}
		return x
	}
	return v
}

func outcomesEx() []any {
	var scs []scenarioEx
	if err := json.Unmarshal([]byte(casesJSONEx), &scs); err != nil {
		panic(err)
	}
	var all []any
	for _, sc := range scs {
		b, _ := json.Marshal(runCaseEx(sc))
		var v any
		_ = json.Unmarshal(b, &v)
		all = append(all, normEx(v))
	}
	return all
}

func runCaseEx(sc scenarioEx) []any {
	clockNowEx = time.Unix(1_700_000_000, 0)
	logBufEx.Reset()
	d := badges.NewScanner(badges.Options{Clock: func() time.Time { return clockNowEx }, Log: &logBufEx})
	var out []any
	for _, o := range sc.Ops {
		switch o.Op {
		case "advance":
			clockNowEx = clockNowEx.Add(time.Duration(o.N[0]) * time.Second)
		case "scan":
			out = append(out, d.Scan(o.S[0], o.S[1]))
		case "seen":
			out = append(out, d.Seen(o.S[0], o.S[1]))
		}
	}
	out = append(out, logBufEx.String())
	return out
}
