package badges_test

import (
	"bytes"
	"encoding/json"
	"reflect"
	"testing"
	"time"

	"example.com/doorcontrol/badges"
)

const casesJSONEx = `[{"Ops": [{"Op": "scan", "S": ["B-99", "store"]}, {"Op": "scan", "S": ["B-22", "lab"]}, {"Op": "scan", "S": ["B-22", "store"]}, {"Op": "seen", "S": ["B-99", "roof"]}, {"Op": "scan", "S": ["B-40", "store"]}, {"Op": "scan", "S": ["B-22", "lab"]}, {"Op": "scan", "S": ["B-40", "roof"]}, {"Op": "scan", "S": ["B-99", "roof"]}, {"Op": "advance", "N": [4]}, {"Op": "scan", "S": ["B-99", "lab"]}, {"Op": "scan", "S": ["B-22", "store"]}, {"Op": "scan", "S": ["B-22", "lab"]}, {"Op": "scan", "S": ["B-17", "server"]}]}, {"Ops": [{"Op": "advance", "N": [30]}, {"Op": "scan", "S": ["B-40", "lab"]}, {"Op": "scan", "S": ["B-22", "lab"]}, {"Op": "scan", "S": ["B-40", "roof"]}, {"Op": "scan", "S": ["B-17", "lab"]}, {"Op": "advance", "N": [5]}, {"Op": "seen", "S": ["B-22", "roof"]}, {"Op": "advance", "N": [1]}]}, {"Ops": [{"Op": "advance", "N": [1]}, {"Op": "scan", "S": ["B-22", "roof"]}, {"Op": "scan", "S": ["B-17", "store"]}, {"Op": "scan", "S": ["B-40", "lab"]}, {"Op": "scan", "S": ["B-99", "lab"]}, {"Op": "advance", "N": [9]}]}]`

var clockNowEx time.Time

var logBufEx bytes.Buffer

type opEx struct {
	Op string
	S  []string
	N  []int
}

type scenarioEx struct {
	Ops []opEx
}

func resEx(v any, err error) any {
	if err != nil {
		return map[string]any{"err": err.Error()}
	}
	return v
}

func normEx(v any) any {
	switch x := v.(type) {
	case []any:
		if len(x) == 0 {
			return nil
		}
		for i := range x {
			x[i] = normEx(x[i])
		}
		return x
	case map[string]any:
		for k := range x {
			x[k] = normEx(x[k])
		}
		return x
	}
	return v
}

func outcomesEx() []any {
	var scs []scenarioEx
	if err := json.Unmarshal([]byte(casesJSONEx), &scs); err != nil {
		panic(err)
	}
	var all []any
	for _, sc := range scs {
		b, _ := json.Marshal(runCaseEx(sc))
		var v any
		_ = json.Unmarshal(b, &v)
		all = append(all, normEx(v))
	}
	return all
}

func runCaseEx(sc scenarioEx) []any {
	clockNowEx = time.Unix(1_700_000_000, 0)
	logBufEx.Reset()
	d := badges.NewScanner(badges.Options{Clock: func() time.Time { return clockNowEx }, Log: &logBufEx})
	var out []any
	for _, o := range sc.Ops {
		switch o.Op {
		case "advance":
			clockNowEx = clockNowEx.Add(time.Duration(o.N[0]) * time.Second)
		case "scan":
			out = append(out, d.Scan(o.S[0], o.S[1]))
		case "seen":
			out = append(out, d.Seen(o.S[0], o.S[1]))
		}
	}
	out = append(out, logBufEx.String())
	return out
}
const wantJSONEx = `[[false, true, true, false, true, false, false, false, false, false, false, true, "denied B-99@store\nopened B-22@lab\nopened B-22@store\nopened B-40@store\nignored repeat B-22@lab\ndenied B-40@roof\ndenied B-99@roof\ndenied B-99@lab\nignored repeat B-22@store\nignored repeat B-22@lab\nopened B-17@server\n"], [false, true, false, true, false, "denied B-40@lab\nopened B-22@lab\ndenied B-40@roof\nopened B-17@lab\n"], [false, true, false, false, "denied B-22@roof\nopened B-17@store\ndenied B-40@lab\ndenied B-99@lab\n"]]`

func TestExampleScenarios(t *testing.T) {
	var want []any
	if err := json.Unmarshal([]byte(wantJSONEx), &want); err != nil {
		t.Fatal(err)
	}
	got := outcomesEx()
	if len(got) != len(want) {
		t.Fatalf("got %d scenarios, want %d", len(got), len(want))
	}
	for i := range want {
		w := normEx(want[i])
		if !reflect.DeepEqual(got[i], w) {
			t.Errorf("scenarioEx %d:\n got  %v\n want %v", i, got[i], w)
		}
	}
}

