	}
	return v
}

func normEx(v any) any {
	switch x := v.(type) {
	case []any:
		if len(x) == 0 {
			return nil
		}
		for i := range x {
			x[i] = normEx(x[i])
		}
		return x
	case map[string]any:
		for k := range x {
			x[k] = normEx(x[k])
		}
		return x
	}
	return v
}

func outcomesEx() []any {
	var scs []scenarioEx
	if err := json.Unmarshal([]byte(casesJSONEx), &scs); err != nil {
		panic(err)
	}
	var all []any
	for _, sc := range scs {
		b, _ := json.Marshal(runCaseEx(sc))
		var v any
		_ = json.Unmarshal(b, &v)
		all = append(all, normEx(v))
	}
	return all
}

func runCaseEx(sc scenarioEx) []any {
	clockNowEx = time.Unix(1_700_000_000, 0)
	d := deckplan.NewPlanner(deckplan.Config{Lanes: 2, LaneLength: 16})
	var out []any
	for _, o := range sc.Ops {
		switch o.Op {
		case "advance":
			clockNowEx = clockNowEx.Add(time.Duration(o.N[0]) * time.Second)
		case "place":
			lane, err := d.Place(deckplan.Vehicle{Plate: o.S[0], Metres: o.N[0], Dangerous: o.N[1] == 1})
			out = append(out, resEx(lane, err))
		case "remaining":
			out = append(out, d.Remaining())
		case "log":
			out = append(out, d.Log())
		}
	}
	return out
}
const wantJSONEx = `[["L1", ["PL-119 -> L1"], "L1", [2, 16], "L1", {"err": "PL-424: length 0 m does not fit a lane of 16 m"}, ["PL-119 -> L1", "PL-804 -> L1", "PL-719 -> L1"], "L2", [0, 14], ["PL-119 -> L1", "PL-804 -> L1", "PL-719 -> L1", "PL-361 -> L2"]], [{"err": "PL-404: length 19 m does not fit a lane of 16 m"}, null, [16, 16], "L1", "L2", ["PL-630 -> L1", "PL-538 -> L2"], {"err": "no space for PL-446"}, "L2", [0, 2], ["PL-630 -> L1", "PL-538 -> L2", "PL-127 -> L2"]], [[16, 16], "L1", "L2", {"err": "PL-958: length 0 m does not fit a lane of 16 m"}, ["PL-359 -> L1", "PL-664 -> L2"], [4, 11], ["PL-359 -> L1", "PL-664 -> L2"]]]`

func TestExampleScenarios(t *testing.T) {
	var want []any
	if err := json.Unmarshal([]byte(wantJSONEx), &want); err != nil {
		t.Fatal(err)
	}
	got := outcomesEx()
	if len(got) != len(want) {
		t.Fatalf("got %d scenarios, want %d", len(got), len(want))
	}
	for i := range want {
		w := normEx(want[i])
		if !reflect.DeepEqual(got[i], w) {
			t.Errorf("scenarioEx %d:\n got  %v\n want %v", i, got[i], w)
		}
	}
}

