var clockNow time.Time

type op struct {
	Op string
	S  []string
	N  []int
}

type scenario struct {
	Ops []op
}

func res(v any, err error) any {
	if err != nil {
		return map[string]any{"err": err.Error()}
	}
	return v
}

func norm(v any) any {
	switch x := v.(type) {
	case []any:
		if len(x) == 0 {
			return nil
		}
		for i := range x {
			x[i] = norm(x[i])
		}
		return x
	case map[string]any:
		for k := range x {
			x[k] = norm(x[k])
		}
		return x
	}
	return v
}

func outcomes() []any {
	var scs []scenario
	if err := json.Unmarshal([]byte(casesJSON), &scs); err != nil {
		panic(err)
	}
	var all []any
	for _, sc := range scs {
		b, _ := json.Marshal(runCase(sc))
		var v any
		_ = json.Unmarshal(b, &v)
		all = append(all, norm(v))
	}
	return all
}

func runCase(sc scenario) []any {
	clockNow = time.Unix(1_700_000_000, 0)
	d := wristbands.NewDesk(wristbands.Options{Clock: func() time.Time { return clockNow }})
	var out []any
	for _, o := range sc.Ops {
		switch o.Op {
		case "advance":
			clockNow = clockNow.Add(time.Duration(o.N[0]) * time.Second)
		case "issue":
			b, err := d.Issue(o.S[0], o.S[1])
			out = append(out, res(b.ID, err))
		case "redeem":
			left, err := d.Redeem(o.N[0])
			out = append(out, res(left, err))
		case "count":
			out = append(out, d.Count(o.S[0]))
		}
	}
	return out
