package wristbands_test

import (
	"encoding/json"
	"reflect"
	"testing"
	"time"

	"example.com/festival/wristbands"
)

const casesJSONEx = `[{"Ops": [{"Op": "issue", "S": ["Ines", "crew"]}, {"Op": "redeem", "N": [101]}, {"Op": "issue", "S": ["Ines", "day"]}, {"Op": "issue", "S": ["Joaquin", "weekend"]}, {"Op": "redeem", "N": [102]}, {"Op": "redeem", "N": [100]}, {"Op": "count", "S": ["day"]}, {"Op": "count", "S": ["weekend"]}]}, {"Ops": [{"Op": "issue", "S": ["Kai", "day"]}, {"Op": "redeem", "N": [100]}, {"Op": "issue", "S": ["Lena", "day"]}, {"Op": "advance", "N": [200000]}, {"Op": "advance", "N": [3600]}, {"Op": "issue", "S": ["Lena", "crew"]}, {"Op": "redeem", "N": [102]}, {"Op": "advance", "N": [600]}, {"Op": "redeem", "N": [103]}, {"Op": "redeem", "N": [100]}, {"Op": "issue", "S": ["Lena", "crew"]}, {"Op": "count", "S": ["day"]}, {"Op": "count", "S": ["weekend"]}]}, {"Ops": [{"Op": "issue", "S": ["Joaquin", "weekend"]}, {"Op": "issue", "S": ["Lena", "weekend"]}, {"Op": "redeem", "N": [102]}, {"Op": "issue", "S": ["Kai", "day"]}, {"Op": "redeem", "N": [101]}, {"Op": "issue", "S": ["Ines", "day"]}, {"Op": "redeem", "N": [103]}, {"Op": "redeem", "N": [100]}, {"Op": "redeem", "N": [100]}, {"Op": "redeem", "N": [100]}, {"Op": "count", "S": ["day"]}, {"Op": "count", "S": ["weekend"]}]}]`

var clockNowEx time.Time

type opEx struct {
	Op string
	S  []string
	N  []int
}

type scenarioEx struct {
	Ops []opEx
}

func resEx(v any, err error) any {
	if err != nil {
		return map[string]any{"err": err.Error()}
	}
	return v
}

func normEx(v any) any {
	switch x := v.(type) {
	case []any:
		if len(x) == 0 {
			return nil
		}
		for i := range x {
			x[i] = normEx(x[i])
		}
		return x
	case map[string]any:
		for k := range x {
			x[k] = normEx(x[k])
		}
		return x
	}
	return v
}

func outcomesEx() []any {
	var scs []scenarioEx
	if err := json.Unmarshal([]byte(casesJSONEx), &scs); err != nil {
		panic(err)
	}
	var all []any
	for _, sc := range scs {
		b, _ := json.Marshal(runCaseEx(sc))
		var v any
		_ = json.Unmarshal(b, &v)
		all = append(all, normEx(v))
	}
	return all
}

func runCaseEx(sc scenarioEx) []any {
	clockNowEx = time.Unix(1_700_000_000, 0)
	d := wristbands.NewDesk(wristbands.Options{Clock: func() time.Time { return clockNowEx }})
	var out []any
	for _, o := range sc.Ops {
		switch o.Op {
		case "advance":
			clockNowEx = clockNowEx.Add(time.Duration(o.N[0]) * time.Second)
		case "issue":
			b, err := d.Issue(o.S[0], o.S[1])
			out = append(out, resEx(b.ID, err))
		case "redeem":
			left, err := d.Redeem(o.N[0])
			out = append(out, resEx(left, err))
		case "count":
			out = append(out, d.Count(o.S[0]))
		}
	}
	return out
}
const wantJSONEx = `[[100, {"err": "no such band 101"}, 101, 102, 2, 9, 1, 1], [100, 0, 101, 102, 9, {"err": "no such band 103"}, {"err": "band 100 is used up"}, 103, 2, 0], [100, 101, {"err": "no such band 102"}, 102, 2, 103, 0, 2, 1, 0, 2, 2]]`

func TestExampleScenarios(t *testing.T) {
	var want []any
	if err := json.Unmarshal([]byte(wantJSONEx), &want); err != nil {
		t.Fatal(err)
	}
	got := outcomesEx()
	if len(got) != len(want) {
		t.Fatalf("got %d scenarios, want %d", len(got), len(want))
	}
	for i := range want {
		w := normEx(want[i])
		if !reflect.DeepEqual(got[i], w) {
			t.Errorf("scenarioEx %d:\n got  %v\n want %v", i, got[i], w)
		}
	}
}
